//
// The parser-to-checker reader. It retains parser token identity, elaborates supported declarations in visibility
// order, resolves uses through c_bindings, and emits expression nodes in the parser's postorder. Parser depths are
// bracket depths and are never used as semantic dependency levels. Unsupported declarators and statements fail
// explicitly; no unresolved name or unrecognized syntax acquires an invented int type.

#include <sys/resource.h>

// Parser token indices are below 1 << 30. The high bit distinguishes a source-only selection retained by a
// declaration/type-query proof from an evaluated selection that may supply an expression graph operand.
#define CHECK_INPUT_SOURCE_SELECTION 0x80000000u

typedef enum CheckInputMessage
{
    CHECK_INPUT_UNSUPPORTED,
    CHECK_INPUT_DECLARATION,
    CHECK_INPUT_UNDECLARED,
    CHECK_INPUT_LITERAL,
    CHECK_INPUT_RESOURCE,
    CHECK_INPUT_REDECLARATION,
    CHECK_INPUT_RETURN,
    CHECK_INPUT_TARGET,
    CHECK_INPUT_INCOMPLETE_MEMBER,
    CHECK_INPUT_INCOMPLETE_OBJECT,
    CHECK_INPUT_LOOP_HINT,
    CHECK_INPUT_LOOP_PLACEMENT,
    // An unroll pragma's count that clang can't read: empty, starting with no expression, unclosed.
    CHECK_INPUT_LOOP_MISSING,
    CHECK_INPUT_LOOP_EXPRESSION,
    CHECK_INPUT_LOOP_PARENTHESIS,
    CHECK_INPUT_NAKED_STATEMENT,
    CHECK_INPUT_NAKED_PARAMETER,
    CHECK_INPUT_KR_IMPLICIT_INT,
    CHECK_INPUT_CONSTANT_INITIALIZER,
    // Clang's parenthesized initializer after attributes or an asm label (#1252), and an array of unknown size's
    // initializer that is no list (#1447), worded by its detail (CheckInputArrayList).
    CHECK_INPUT_DIRECT_INITIALIZER_ARRAY,
    CHECK_INPUT_DIRECT_INITIALIZER_DEDUCED,
    // A field designator that names no member of the record in CheckInputReport.type.
    CHECK_INPUT_INITIALIZER_MEMBER,
    // An array initialized by a compound literal of another array type (#1447, GNU's extension): the array's type in
    // CheckInputReport.type, the literal's in its value.
    CHECK_INPUT_ARRAY_LITERAL_MISMATCH,
    // C23's incompatible redefinition of a record (#1447, c_check_tag_compatible.c): its first difference in
    // CheckInputReport.detail (CheckTagMismatch), its notes' tokens in attribute and note_token, their members' types in
    // type and value, and bit-fields' widths in bit_widths.
    CHECK_INPUT_TAG_INCOMPATIBLE,
    // An undeclared value's name that a typo corrects (#1447, c_check_typo.c), recovered: the declaration it takes in
    // CheckInputReport.note_token, "did you mean" its name and "declared here" at it.
    CHECK_INPUT_UNDECLARED_CORRECTED,
    // #pragma clang section's errors and section type conflicts, each with its message (CheckInputSections.diagnostics).
    CHECK_INPUT_SECTION,
    // #pragma clang optimize's errors, each with its message (CheckInputOptimizePragmas.diagnostics).
    CHECK_INPUT_OPTIMIZE,
    // A goto, a switch's case, a computed goto and an asm goto that enter a variable-length array's or a cleanup's scope,
    // or for a computed goto and an asm goto leave a cleanup's, as clang's JumpScopeChecker reports them.
    CHECK_INPUT_JUMP_GOTO,
    CHECK_INPUT_JUMP_SWITCH,
    CHECK_INPUT_JUMP_INDIRECT,
    CHECK_INPUT_JUMP_ASM,
    // GNU's cleanup attribute's argument and function (c_check_cleanup_input.c).
    CHECK_INPUT_CLEANUP_FUNCTION,
    CHECK_INPUT_CLEANUP_PARAMETERS,
    CHECK_INPUT_CLEANUP_TYPE,
    CHECK_INPUT_CLEANUP_ARGUMENTS,
    // GNU's weak attribute on a declaration without external linkage.
    CHECK_INPUT_WEAK_LINKAGE,
    // GNU's alias and ifunc attributes on a definition, or after another that makes the declaration one (#147): clang's
    // "definition 'f' cannot also be an alias" (or "an ifunc"), at the attribute, naming the declaration (the report's
    // subject).
    CHECK_INPUT_ALIAS_DEFINITION,
    CHECK_INPUT_IFUNC_DEFINITION,
    // A variable's alias after a tentative definition of it (#147, clang's checkNewAttributesAfterDef): "alias definition
    // of 'x' after tentative definition", at its name, with the note "previous definition is here" at the last one.
    CHECK_INPUT_ALIAS_TENTATIVE,
    // GNU's weakref attribute (#147): on a declaration with external linkage, at the attribute; in a block, or without a
    // target (its argument, or an alias attribute beside it), naming the declaration; and on a typedef.
    CHECK_INPUT_WEAKREF_LINKAGE,
    CHECK_INPUT_WEAKREF_CONTEXT,
    CHECK_INPUT_WEAKREF_ALIAS,
    CHECK_INPUT_WEAKREF_SUBJECT,
    // Labels' errors, at the label's name (check_input_controls_mode): a use of one no definition has, or a local
    // label's declaration without one; a second definition in the label's scope; a name a block's `__label__` lists
    // declare twice.
    CHECK_INPUT_LABEL_UNDECLARED,
    CHECK_INPUT_LABEL_REDEFINITION,
    CHECK_INPUT_LABEL_AMBIGUOUS,
    // __auto_type's errors (check_input_auto_type_declarator, check_input_auto_type_finish): a variable's without an
    // initializer, at its name, and one whose initializer names it, at the name there; a place other than a variable's
    // declaration, at the keyword; an initializer list's and an array's, at the initializer; a bit-field's value.
    CHECK_INPUT_AUTO_TYPE_INITIALIZER,
    CHECK_INPUT_AUTO_TYPE_SELF,
    CHECK_INPUT_AUTO_TYPE_CONTEXT,
    CHECK_INPUT_AUTO_TYPE_LIST,
    CHECK_INPUT_AUTO_TYPE_ARRAY,
    CHECK_INPUT_AUTO_TYPE_BIT_FIELD,
    // C23's `auto` type specifier (#793): the same errors as __auto_type's, naming `auto` where clang does, and two
    // declarators of one declaration whose deductions differ.
    CHECK_INPUT_AUTO_DEDUCED_INITIALIZER,
    CHECK_INPUT_AUTO_DEDUCED_SELF,
    CHECK_INPUT_AUTO_DEDUCED_CONTEXT,
    CHECK_INPUT_AUTO_DEDUCED_LIST,
    CHECK_INPUT_AUTO_DEDUCED_ARRAY,
    CHECK_INPUT_AUTO_DEDUCED_BIT_FIELD,
    CHECK_INPUT_AUTO_DEDUCED_MISMATCH,
    // __auto_type's declarators of differing deductions (#147).
    CHECK_INPUT_AUTO_TYPE_MISMATCH,
    // C23's constexpr (#793): an initializer that isn't a constant expression; a pointer's that isn't null; a place
    // other than an initialized object's definition.
    CHECK_INPUT_CONSTEXPR_INITIALIZER,
    CHECK_INPUT_CONSTEXPR_POINTER,
    CHECK_INPUT_CONSTEXPR_REPRESENTABLE,
    CHECK_INPUT_CONSTEXPR_CONTEXT,
    // A bit-precise constant wider than BITINT_MAXWIDTH (BUSTER_CHECK_WIDE_MAX_WIDTH, #768, #1447).
    CHECK_INPUT_WIDE_LITERAL,
    CHECK_INPUT_PRAGMA_SEMANTICS,
    // clang's musttail attribute (#147) where it doesn't go, at the attribute: with arguments, on a declaration (a label
    // among them), and on a statement other than a return.
    CHECK_INPUT_MUSTTAIL_ARGUMENTS,
    CHECK_INPUT_MUSTTAIL_DECLARATION,
    CHECK_INPUT_MUSTTAIL_STATEMENT,
    // A GNU attribute on a label that clang refuses there (check_input_label_refusal), at its name (#147).
    CHECK_INPUT_LABEL_ATTRIBUTE,
    // A statement's attribute that clang refuses on a statement, and fallthrough on one that isn't empty, at its name
    // (#147, check_input_statement_attribute_kinds).
    CHECK_INPUT_STATEMENT_ATTRIBUTE,
    // An attribute on a declaration of none of its subjects, which clang makes an error (#147, check_input_attribute_subjects).
    CHECK_INPUT_ATTRIBUTE_SUBJECT,
    CHECK_INPUT_FALLTHROUGH_STATEMENT,
    // A fallthrough null statement outside a switch, at the attribute's name, and one in a switch whose next statement
    // isn't a case or default label, at its first token (check_input_fallthrough_placed).
    CHECK_INPUT_FALLTHROUGH_SWITCH,
    CHECK_INPUT_FALLTHROUGH_PLACEMENT,
    // __builtin_verbose_trap's arguments (#148), at the argument's first token: one that is no constant, and a string
    // with a `$` (check_input_verbose_trap_arguments).
    CHECK_INPUT_VERBOSE_TRAP_STRING,
    CHECK_INPUT_VERBOSE_TRAP_DOLLAR,
    // __builtin_longjmp's second argument (#148), at the call's first token: one that is no integer constant, and a
    // constant other than 1 (check_input_longjmp_argument).
    CHECK_INPUT_LONGJMP_INTEGER,
    CHECK_INPUT_LONGJMP_ONE,
    // A FILE builtin's call (__builtin_fprintf and its kin, #148) in a unit without a file-scope FILE, which its prototype
    // takes (check_input_file_type), at the name: clang's "use of unknown builtin".
    CHECK_INPUT_UNKNOWN_BUILTIN,
    CHECK_INPUT_INVOKE_ARGUMENTS,
    // A unary, overflow or complex part builtin's call with another count of arguments (#1860), which the graph doesn't
    // take: clang's "too few/too many arguments to function call", the count it takes and the call's in the detail's low
    // and high halves, at the call's `)` (too few) or its first extra argument.
    CHECK_INPUT_BUILTIN_ARGUMENT_COUNT,
    CHECK_INPUT_BUILTIN_NOT_CALLED,
    // A declaration with external linkage of a builtin's name (#1843, check_input_builtin_declaration), at its name: one
    // whose type isn't compatible with the builtin's (clang's "conflicting types", with its note of the builtin's type, the
    // report's), and a definition of one (clang's err_builtin_definition).
    CHECK_INPUT_BUILTIN_CONFLICT,
    CHECK_INPUT_BUILTIN_DEFINITION,
    // Any declaration with external linkage of a custom-checked builtin's name (#1918's review, clang's
    // err_builtin_redeclare: "cannot redeclare builtin function"), with the same note.
    CHECK_INPUT_BUILTIN_REDECLARE,
    CHECK_INPUT_ATTRIBUTE_OUT_OF_BOUNDS,
    CHECK_INPUT_ATTRIBUTE_TYPES,
    CHECK_INPUT_ATTRIBUTE_LIST_PLACE,
    // A C23 attribute list before a file-scope declaration of a tag alone (#147): clang's parser's "misplaced attributes;
    // expected attributes here", just after the tag's keyword (the report's token).
    CHECK_INPUT_ATTRIBUTES_MISPLACED,
    // An enumerator's value an enum's underlying type (CheckInputReport.type, its typedef's spelling in type_spelling)
    // can't represent: "enumerator value is not representable in the underlying type 'T'", or, for the one after the
    // largest (detail 1), "enumerator value V is not representable ..." (CheckInputReport.value).
    CHECK_INPUT_ENUM_NOT_REPRESENTABLE,
    CHECK_INPUT_ATTRIBUTE_CONVENTIONS,
    CHECK_INPUT_VECTOR_ELEMENT,
    CHECK_INPUT_VECTOR_BIT_INT,
    CHECK_INPUT_VECTOR_CONSTANT,
    CHECK_INPUT_VECTOR_NEGATIVE,
    CHECK_INPUT_VECTOR_TOO_LARGE,
    CHECK_INPUT_VECTOR_ZERO,
    CHECK_INPUT_VECTOR_MULTIPLE,
    // The address-space qualifiers' errors (#1447), clang's: address_space's argument (no integer constant, negative, past
    // the largest), at the attribute; a function type's, and a second space on a type, at the attribute; and the
    // declarations a space can't qualify, at their names (a compound literal's at its `(`).
    CHECK_INPUT_ADDRESS_SPACE_CONSTANT,
    CHECK_INPUT_ADDRESS_SPACE_NEGATIVE,
    CHECK_INPUT_ADDRESS_SPACE_TOO_HIGH,
    CHECK_INPUT_ADDRESS_SPACE_FUNCTION,
    CHECK_INPUT_ADDRESS_SPACE_MULTIPLE,
    CHECK_INPUT_ADDRESS_SPACE_AUTOMATIC,
    CHECK_INPUT_ADDRESS_SPACE_PARAMETER,
    CHECK_INPUT_ADDRESS_SPACE_FIELD,
    CHECK_INPUT_ADDRESS_SPACE_COMPOUND,
    // Two garbage collection qualifiers on one type (#1447): objc_gc's weak and strong.
    CHECK_INPUT_GC_MULTIPLE,
    CHECK_INPUT_ATTRIBUTE_ARGUMENT_COUNT,
    CHECK_INPUT_ATTRIBUTE_EXCLUSION,
    CHECK_INPUT_ATTRIBUTE_ANNOTATE_STRING,
    CHECK_INPUT_UNAVAILABLE_USE,
    // GNU's function multiversioning: a function attribute clang refuses beside target("default"), target_clones or
    // cpu_specific/cpu_dispatch, at the function's name, naming the attribute; and a target attribute incompatible with
    // another multiversioning attribute, at the later attribute, with a note at the earlier one.
    CHECK_INPUT_MULTIVERSION_ATTRIBUTE,
    CHECK_INPUT_MULTIVERSION_INCOMPATIBLE,
    CHECK_INPUT_MULTIVERSION_DUPLICATE,
    // clang's no_builtin on a function declaration, which isn't a definition.
    CHECK_INPUT_NO_BUILTIN_DEFINITION,
    // Declaration specifiers that don't combine, as clang's DeclSpec words it (c_check_declspec.c, #1127): a conflict
    // with an earlier specifier of the same kind, a signed or unsigned type that can't be, a width or _Complex that the
    // type doesn't take. The report's `specifier` and `specifier_type` say which specifiers the message names.
    CHECK_INPUT_SPECIFIER_COMBINE,
    CHECK_INPUT_SPECIFIER_SIGN,
    CHECK_INPUT_SPECIFIER_WIDTH,
    CHECK_INPUT_SPECIFIER_COMPLEX,
    // __builtin_available's specs (#148, c_check_availability_input.c), as clang's parser reports them: a number that is
    // no version, at it; a zero version, at the token after it; a platform clang doesn't know, at its name; an
    // anyAppleOS version below 26, at it; a platform's second version, at its name (`detail` the platform); a second
    // `*`, at it; and no `*`, just past the last version.
    CHECK_INPUT_AVAILABILITY_VERSION,
    CHECK_INPUT_AVAILABILITY_ZERO,
    CHECK_INPUT_AVAILABILITY_PLATFORM,
    CHECK_INPUT_AVAILABILITY_APPLE,
    CHECK_INPUT_AVAILABILITY_REPEATED,
    CHECK_INPUT_AVAILABILITY_STAR,
    CHECK_INPUT_AVAILABILITY_WILDCARD,
    // The counted_by family's errors (#148, c_check_counted_by_input.c), clang's CheckCountedByAttrOnField's, `detail` the
    // attribute's kind less one, with 0x100 for an array member and the pointee's fault in bits 16 to 23: on a union's
    // member; on a member of neither pointer nor flexible array type (or an array, of a sized_by or an _or_null one); on
    // an array of a constant bound; of a pointee or an element of unknown size (the report's type); and of its count, of
    // no integer type, no plain name, no member (a note at its declaration), a union's member, another struct's member
    // (a note at it); and of the argument's syntax, clang's parser's: none in the parentheses, more than one.
    CHECK_INPUT_COUNTED_UNION,
    CHECK_INPUT_COUNTED_SUBJECT,
    CHECK_INPUT_COUNTED_ARRAY,
    CHECK_INPUT_COUNTED_POINTEE,
    CHECK_INPUT_COUNTED_INTEGER,
    CHECK_INPUT_COUNTED_REFERENCE,
    CHECK_INPUT_COUNTED_OUTSIDE,
    CHECK_INPUT_COUNTED_UNION_FIELD,
    CHECK_INPUT_COUNTED_STRUCT,
    CHECK_INPUT_COUNTED_REQUIRED,
    CHECK_INPUT_COUNTED_PAREN,
    // __builtin_counted_by_ref's value where clang's CheckInvalidBuiltinCountedByRef refuses it (#148), at the call: `detail`
    // 0 assigned, 1 passed, 2 returned; and 0 in a subscript's base, 1 a binary operator's operand.
    CHECK_INPUT_COUNTED_REF_LEAK,
    CHECK_INPUT_COUNTED_REF_USE,
    // clang's errors of lifetimebound, loader_uninitialized and internal_linkage (#147): lifetimebound on a parameter of a
    // function that returns void, and a C23 one on a function's type, at the attribute; loader_uninitialized on a variable
    // with an initializer or an extern one,
    // at its name, and added to a variable after its definition, at the attribute (a note at the definition);
    // internal_linkage that a function's or variable's first declaration hasn't, at its name (a note at that one).
    CHECK_INPUT_LIFETIMEBOUND_VOID,
    CHECK_INPUT_LIFETIMEBOUND_OBJECT,
    CHECK_INPUT_LOADER_INITIALIZER,
    CHECK_INPUT_LOADER_EXTERN,
    CHECK_INPUT_LOADER_REDECLARATION,
    CHECK_INPUT_INTERNAL_LINKAGE_FIRST,
    // The thread-safety attributes' handlers' errors (#147, c_check_thread_safety_input.c): capability's name no string
    // literal, at it (the report's attribute its first token); a trylock's first argument no int or bool, and a lock
    // function's parameter index out of bounds (`detail` the argument's place from 1, the parameters' count in bits 16 and
    // up), at the attribute.
    CHECK_INPUT_ATTRIBUTE_STRING_ARGUMENT,
    CHECK_INPUT_ATTRIBUTE_INT_OR_BOOL,
    CHECK_INPUT_ATTRIBUTE_INDEX_BOUNDS,
    // An attribute's argument's error as clang's handler words it (#147, c_check_attribute.c's CheckAttributeArgumentError
    // in `detail`'s low byte, a number above it), the attribute named by its first token (the report's attribute).
    CHECK_INPUT_ATTRIBUTE_ARGUMENT,
    CHECK_INPUT_BREAK,
    CHECK_INPUT_CONTINUE,
    CHECK_INPUT_INCOMPLETE_TENTATIVE,
    CHECK_INPUT_ENUMERATOR_REDEFINITION,
    CHECK_INPUT_CONFLICTING_TYPES,
    // A declaration of no declarator (#147, clang's ParsedFreeStandingDeclSpec): restrict, at its first; and inline and
    // _Noreturn, at theirs. Each is clang's error, after which it goes on to
    // its warning that the declaration declares nothing.
    CHECK_INPUT_RESTRICT_NOT_POINTER,
    CHECK_INPUT_INLINE_NOT_FUNCTION,
    CHECK_INPUT_NORETURN_NOT_FUNCTION,
    // The current type table stores alignments as powers of two; some wide Microsoft bit-field units need others.
    CHECK_INPUT_MS_STRUCT_ALIGNMENT,
    // __FLT_EVAL_METHOD__ expanded after an eval_method pragma in its active scope. The subject is the cold PP
    // expansion-use index plus one, detail its publication boundary, and value the active pragma's output token.
    CHECK_INPUT_FP_EVAL_USE,
    // A typedef whose available_only_in_default_eval_method attribute forbids the active pragma's evaluation method.
    CHECK_INPUT_FP_EVAL_TYPE,
    // An escape sequence clang refuses in an unevaluated string literal (#147, check_literal_unevaluated_escapes): an
    // attribute's string argument's, which clang then drops, or a static assertion's message's, which drops the assertion.
    // At the first string token that has one; `detail` the literal's end (its last token plus one). The driver words each
    // of the literal's escapes' diagnostics, at its backslash. A dropped C23 standard attribute's report gives clang's
    // parser's error of the attribute before it too: `value` its `(` plus one (bit 32 where that one takes no arguments),
    // `attribute` its name (check_input_attribute_standard_previous).
    CHECK_INPUT_UNEVALUATED_ESCAPE,
    // x86's interrupt (#147): a declaration its handler refuses (check_input_interrupt_handler, `detail` which of its four
    // rules, BUSTER_CHECK_INTERRUPT_UNLOCATED where clang gives the error no place), and a direct call of an interrupt
    // service routine, at its callee (check_input_interrupt_calls).
    CHECK_INPUT_INTERRUPT_HANDLER,
    CHECK_INPUT_INTERRUPT_CALLED,
    // An asm operand's constraint that clang's validateOutputConstraint or validateInputConstraint refuses (#1973,
    // check_asm_clang_valid), at its string: `value` its bytes' address in the reader's arena, `detail` their length and
    // BUSTER_CHECK_ASM_OUTPUT for an output's.
    CHECK_INPUT_ASM_CONSTRAINT,
    // A global register variable (#1846): `register` at file scope without an asm label, clang's "illegal storage class on
    // file-scoped variable", at its name; an explicit register variable's label (a local's too) that names no register
    // clang knows, a global's of a register clang's backend can't keep one in, or of another size than its type
    // (CHECK_INPUT_REGISTER_NAME at the label's string: `value` the name's bytes' address in the reader's arena, `detail`
    // their length and BUSTER_CHECK_REGISTER_NAME_UNSUITABLE or _SIZE); and a global's type that is neither an integer nor
    // a pointer, at its type specifier.
    CHECK_INPUT_FILE_REGISTER,
    CHECK_INPUT_REGISTER_NAME,
    CHECK_INPUT_REGISTER_TYPE,
    // A function's redeclaration with another explicit calling convention (#1447, check_input_report_redeclaration): the
    // new and the first declaration's conventions in the detail's low bytes, and in its bit 16 whether the first's is explicit.
    CHECK_INPUT_CONVENTION_CHANGE,
    // diagnose_if's and enable_if's (#1447, c_check_condition.c): an error diagnose_if's condition gives, its message at the
    // call's `)` (or at the use of a function whose condition no argument decides), its note "from 'diagnose_if' attribute
    // on 'f':" at the attribute (`note_token`), the message's first string token plus one in `detail` and the function's
    // name's token in `value`; a call no enable_if condition admits, "no matching function for call to 'f'" at the callee,
    // its note "candidate disabled: M" at the function's declaration (`note_token`), M's token plus one in `detail`; and a
    // use of a function with a condition that isn't always true other than a call's, "cannot take address of function 'f'
    // because it has one or more non-tautological enable_if conditions", at the outermost `(` around the name (`value`).
    CHECK_INPUT_DIAGNOSE_IF_ERROR,
    CHECK_INPUT_ENABLE_IF_CALL,
    CHECK_INPUT_ENABLE_IF_ADDRESS,
    // clang's cpu_specific and cpu_dispatch multiversioning (#1447, c_check_cpu_dispatch.c): `detail` which of its errors
    // (CheckCpuDispatchError), `attribute` a CPU's token the message names, `value` 1 for cpu_dispatch's option, and a note
    // at `note_token` where it has one.
    CHECK_INPUT_CPU_DISPATCH,
    // A block's extern declaration with an initializer, at its name (#1447): clang's "declaration of block scope identifier
    // with linkage cannot have an initializer".
    CHECK_INPUT_BLOCK_EXTERN_INITIALIZER,
    // clang's declarator errors (#1447, Sema's BuildArrayType and BuildFunctionType): a function's return type of array or
    // function type in CheckInputReport.type, at its `(`, "function cannot return array type 'int[3]'"; an array bound's
    // negative constant, at it, "'a' declared as an array with a negative size" (its name's token in `value`, or
    // BUSTER_CHECK_NONE: "array size is negative"); and an element type at the array's `[`, in `type`: a function's,
    // "'a' declared as array of functions of type 'int (void)'" (the name in `value`), and an incomplete one's, "array has
    // incomplete element type 'struct S'", with a tag's forward declaration's note.
    CHECK_INPUT_FUNCTION_RETURN,
    CHECK_INPUT_ARRAY_NEGATIVE,
    CHECK_INPUT_ARRAY_FUNCTIONS,
    CHECK_INPUT_ARRAY_INCOMPLETE,
    // An invalid function's initializer (#1447): clang's "illegal initializer (only variables can be initialized)", at its
    // name, recovered and the initializer skipped.
    CHECK_INPUT_FUNCTION_INITIALIZER,
    // An array's element whose size isn't a multiple of its alignment (#1893, clang's err_array_element_alignment), at the
    // array's `[`: the element type, its size in `value` and its alignment in `detail`.
    CHECK_INPUT_ARRAY_ELEMENT_ALIGNMENT,
    // An array of more than BUSTER_TYPE_MAX_OBJECT_BYTES (#1447, clang's limit too), at its bound: "array is too large
    // (2'305'843'009'213'693'952 elements)", its count in `value`.
    CHECK_INPUT_ARRAY_TOO_LARGE,
    // An array bound of a type that isn't an integer's (#2170, clang's err_array_size_non_int), at the bound's first token:
    // "size of array has non-integer type 'double'", the bound's type in `type`.
    CHECK_INPUT_ARRAY_NON_INTEGER,
    // A list of specifiers whose only type specifier was a _BitInt with an undeclared name in its width (#1447), which clang
    // drops: its parser's error at the list's end, by `detail`: 0 "type specifier missing, defaults to 'int'; ISO C99 and
    // later do not support implicit int [-Wimplicit-int]", 1 C23's "a type specifier is required for all declarations",
    // 2 a type name's or a member's "type name requires a specifier or qualifier", 3 a C23 parameter's name's "unknown type
    // name 'a'".
    CHECK_INPUT_TYPE_SPECIFIER_MISSING,
    // A declarator's constant's error in clang's words (#1447, check_input_constant_failure_report): a missing member, a
    // member access's base, `sizeof` of an incomplete type, a call's argument count, a binary operator's operands or
    // pointer arithmetic on an incomplete pointee, as CHECK_INPUT_ATTRIBUTE_ARGUMENT's (its CheckAttributeArgumentError in
    // `detail`), at the failing token.
    CHECK_INPUT_CONSTANT_EXPRESSION,
    // A variable-length array or variably modified type where C allows none (#1447, check_input_vla_place), each at its
    // declarator's name as clang's: at file scope, a block's static or extern object, a member.
    CHECK_INPUT_VLA_FILE_SCOPE,
    CHECK_INPUT_VM_FILE_SCOPE,
    CHECK_INPUT_VLA_STATIC,
    CHECK_INPUT_VLA_EXTERN,
    CHECK_INPUT_VM_EXTERN,
    CHECK_INPUT_VLA_FIELD,
    // A block's automatic variable-length array with an initializer but an empty list (#1447): clang's "variable-sized
    // object may not be initialized", at the outermost bound for a list, else at the name; recovered, the declaration
    // valid and its initializer unchecked (CheckInputReader.vla_initializer_dropped).
    CHECK_INPUT_VLA_INITIALIZER,
    // clang's parser's second error after a GNU suppress it drops for a malformed argument (#1844,
    // check_input_suppress_dropped): the statement after it, its block item's GNU attributes all gone, parsed as a
    // declaration, whose first token starts no declarator.
    CHECK_INPUT_DROPPED_SUPPRESS_DECLARATION,

    // A use of an invalid declaration (#1447, check_input_invalid_declare), at its name: no diagnostic of its own, as
    // clang's RecoveryExpr has none, but the uses' and their enclosing expressions' are left out as an undeclared name's
    // are (CHECK_INPUT_UNDECLARED's completion, check_input_diagnostic_recover). The driver publishes nothing for it and
    // counts it as no error of its scope (check_driver_error_counts).
    CHECK_INPUT_INVALID_USE,
    // A use of a name that two C23 definitions of an enum both declare (#1447, check_tag_enum_ambiguous): clang's
    // "reference to 'X' is ambiguous" at it, its notes "candidate found by name lookup is 'X'" at the second definition's
    // enumerator (`note_token`) and the earlier's (`attribute`). Its enclosing expressions' diagnostics are left out as an
    // undeclared name's are.
    CHECK_INPUT_AMBIGUOUS,
    // A redeclaration whose asm label differs from an earlier declaration's (#2262, check_input_asm_labels): clang's
    // "conflicting asm label" at its name, its note "previous declaration is here" at the earlier label's string
    // (`note_token`).
    CHECK_INPUT_ASM_LABEL_CONFLICT,
    // A `case` or a `default` label outside any switch (#2406): clang's "'case' statement not in switch statement" (or
    // 'default') at its keyword.
    CHECK_INPUT_CASE_OUTSIDE_SWITCH,
    CHECK_INPUT_DEFAULT_OUTSIDE_SWITCH,
} CheckInputMessage;

