// The type/action tables currently describe one C LP64 model: 32-bit wchar_t, x87 long double stored in 16 bytes, and
// arithmetic evaluated in its source format, with plain char signed or unsigned as the options say
// (TypeTable.char_unsigned). Refuse preprocessing options that advertise a different model before applying those fixed
// tables to the source.
static bool check_input_target_supported(const PPOptions* options)
{
    const PredefinesOptions* target = &options->predefines;
    const bool source_evaluation = target->fp_eval_method == BUSTER_PREDEFINES_EVAL_SOURCE ||
                                   (target->fp_eval_method == BUSTER_PREDEFINES_EVAL_DEFAULT && predefines_eval_method(target) == 0);
    return !options->assembly && !target->short_wchar && target->long_double == BUSTER_PREDEFINES_LONG_DOUBLE_80 && source_evaluation;
}

// CheckInputReader.enum_fixed: an enum without a fixed underlying type (or another tag), one with it whose enumerators
// aren't listed yet, and one with them.
#define BUSTER_CHECK_ENUM_NONE 0
#define BUSTER_CHECK_ENUM_FIXED 1
#define BUSTER_CHECK_ENUM_LISTED 2
// An enum a mode before its body completed (#147, check_input_enum_mode): its explicit values must be representable in the
// mode's type, as a fixed one's, but its enumerators are a plain enum's.
#define BUSTER_CHECK_ENUM_MODED 3

// The note a report carries, if any: clang's note at the earlier attribute of an incompatible multiversioning pair, at
// the declaration that caused a function to be multiversioned, at a naked function's attribute, or at a redefined label's
// first definition.
typedef enum CheckInputNoteKind
{
    CHECK_INPUT_NOTE_NONE,
    CHECK_INPUT_NOTE_CONFLICTING_ATTRIBUTE,
    CHECK_INPUT_NOTE_MULTIVERSIONING_CAUSED,
    CHECK_INPUT_NOTE_ATTRIBUTE_HERE,
    CHECK_INPUT_NOTE_PREVIOUS_DEFINITION,
    CHECK_INPUT_NOTE_UNAVAILABLE_HERE,
    // The declaration of a counted_by family attribute's count (#148): "field 'n' declared here".
    CHECK_INPUT_NOTE_COUNTED_FIELD,
    // The attribute's `(`, which a second argument's `,` doesn't match (#148): "to match this '('".
    CHECK_INPUT_NOTE_MATCH_PAREN,
    // A declaration before the one a message is about (#147): "previous declaration is here".
    CHECK_INPUT_NOTE_PREVIOUS_DECLARATION,
    // A statement's earlier attribute of the same kind (#147, code_align's): "previous attribute is here".
    CHECK_INPUT_NOTE_PREVIOUS_ATTRIBUTE,
    // An incomplete tag's declaration (#147, preferred_type's type): "forward declaration of 'struct S'", the report's type.
    CHECK_INPUT_NOTE_FORWARD_DECLARATION,
    CHECK_INPUT_NOTE_FUNCTION_DECLARATION,
    CHECK_INPUT_NOTE_CONSTANT_SUBEXPRESSION,
    CHECK_INPUT_NOTE_CONSTANT_DIVISION,
    // A jump's scope it enters (#1942): a statement expression's `(`, "jump enters a statement expression".
    CHECK_INPUT_NOTE_JUMP,
    // A condition's cast clang's constant evaluation refuses (#2253, check_condition_cast): to void, "non-literal type 'void'
    // cannot be used in a constant expression"; between an integer and a pointer, "this conversion is not allowed in a
    // constant expression".
    CHECK_INPUT_NOTE_CONSTANT_VOID,
    CHECK_INPUT_NOTE_CONSTANT_CONVERSION,
} CheckInputNoteKind;

// A version as clang's VersionTuple holds it (#1447: an availability attribute's): its components (major, minor,
// subminor, the minor and subminor in 31 bits) and how many were written (0: none, an empty version).
typedef struct CheckVersionTuple CheckVersionTuple;
struct CheckVersionTuple
{
    uint32_t major;
    uint32_t minor;
    uint32_t subminor;
    uint32_t components;
};

// What an availability attribute's warning prints past its location (#1447, CHECK_WARNING_EVENT_AVAILABILITY_ORDERING's
// and CHECK_WARNING_EVENT_AVAILABILITY_VERSION's payload.data indexes CheckInput.availability_texts): the platform's token
// (its pretty name, or its name as written, as clang's messages print it), and two stages (0 introduced, 1 deprecated, 2
// obsoleted) and their versions; an invalid version's warning prints the first version and its note the second.
typedef struct CheckInputAvailabilityText CheckInputAvailabilityText;
struct CheckInputAvailabilityText
{
    uint32_t platform;
    uint32_t first_stage;
    uint32_t second_stage;
    CheckVersionTuple first;
    CheckVersionTuple second;
};

typedef struct CheckInputReport CheckInputReport;
struct CheckInputReport
{
    uint32_t token;
    CheckInputMessage message;
    uint32_t pragma;
    // Zero uses the located token. Otherwise this is a proven parser-token publication boundary; count + 1 is TU end.
    uint32_t completion;
    // Optional order among a completed declaration's diagnostics, whose locations need not follow that order.
    uint64_t suborder;
    // The declaration a message located elsewhere names, or a redeclaration's prior declaration, plus one; 0 for none.
    uint32_t subject;
    // The attribute a multiversioning message names (its name token), or BUSTER_CHECK_NONE.
    uint32_t attribute;
    // An attribute's argument a message names, from 1 (CHECK_INPUT_ATTRIBUTE_OUT_OF_BOUNDS's); two calling conventions
    // (CHECK_INPUT_ATTRIBUTE_CONVENTIONS's, the one asked for in the low byte); or 0.
    uint32_t detail;
    // The value a message prints (CHECK_ARGUMENT_TOO_LARGE's), the times a CHECK_INPUT_UNAVAILABLE_USE is given again
    // (a tag's, once for each declarator, #147), CHECK_INPUT_FP_EVAL_USE's pragma output token, or 0.
    uint64_t value;
    // The type a message names (CHECK_INPUT_VECTOR_ELEMENT's), and its typedef specifier's declaration
    // (check_input_typedef_spelling), or 0.
    TypeId type;
    uint32_t type_spelling;
    // The note's token and kind (CheckInputNoteKind), or BUSTER_CHECK_NONE and CHECK_INPUT_NOTE_NONE.
    uint32_t note_token;
    uint8_t note_kind;
    // The multiversioning kind a message names (CheckInputMultiversionKind, c_check_attribute.c), or 0.
    uint8_t multiversion;
    // The specifiers a CHECK_INPUT_SPECIFIER_* message names (CheckDeclspecName, c_check_declspec.c), or 0.
    uint8_t specifier;
    uint8_t specifier_type;
    // A token to order this report by instead of `token`, or 0: an alias definition's error is clang's after the
    // multiversioning error at the function's name, though its attribute is earlier.
    uint32_t sort;
    // Keep this report even when another at its token comes first: clang's multiversioning check repeats the earlier
    // declaration's error when a later declaration makes it a version.
    bool repeated;
    // An error that didn't stop the reader (CheckInput.recovered_reports): it rejects the unit, but the diagnostics'
    // cutoffs after the reader don't end at it.
    bool recovered;
    // A recovered error that waits for its declarator's completion (CheckInputReader.recovered_pending).
    bool pending;
    // CHECK_INPUT_TAG_INCOMPATIBLE's bit-fields' widths, each plus one (0 for no bit-field), the second definition's in
    // the high half; else 0.
    uint32_t bit_widths;
};

static __attribute__((unused)) uint32_t check_input_report_source(const Parser* parser, const CheckInputReport* report)
{
    return report->pragma != 0 ? (report->pragma <= parser->tokens.pragma_count ? parser->tokens.pragma_sources[report->pragma - 1] + 1 : BUSTER_CHECK_NONE) :
           report->token < parser->tokens.count ? parser->tokens.sources[report->token] : BUSTER_CHECK_NONE;
}

// Sparse source diagnostics, including calls checked only by sizeof/typeof rather than a retained graph.
typedef struct CheckInputKrDiagnostic CheckInputKrDiagnostic;
struct CheckInputKrDiagnostic
{
    uint32_t token;
    uint32_t warning;
    // A definition diagnostic's body opening, where clang completes the warning when the function's checking does:
    // its body's own diagnostics publish first, ahead of the same boundary's deferred and return ones (#992). A call's:
    // its callee's name, which names the function and chooses the severity, where `token` is clang's place for it
    // (check_input_kr_call), or BUSTER_CHECK_NONE where `token` is the name itself.
    uint32_t body;
};

// The class codes the visits byte's bits 2 to 6 hold (CheckInputExpressionCode, BUSTER_CHECK_EXPRESSION_CODE_MASK).
#define BUSTER_CHECK_EXPRESSION_CODES 32u
// The expressions' walk's parts, whose TSC ticks --time-stages reports within its row (#1038): the classes' pass
// (check_input_expression_classes), the coded walk's chunks' preparation (the compaction and the identifiers' leaves),
// its classes' own actions, and the walk's visits (check_input_expression_visit: in a coded unit those of the tokens
// the classes' actions leave, two TSC reads each; in a unit the coded walk leaves to the visit throughout, and on the
// scalar path, the whole of its actions). Preparation and the classes' actions are the coded walk's, 0 on the scalar
// path.
#define BUSTER_CHECK_EXPRESSION_PART_CLASSES 0u
#define BUSTER_CHECK_EXPRESSION_PART_PREPARE 1u
#define BUSTER_CHECK_EXPRESSION_PART_ACTIONS 2u
#define BUSTER_CHECK_EXPRESSION_PART_VISITS 3u
#define BUSTER_CHECK_EXPRESSION_PARTS 4u

